import json
from pathlib import Path
from shapely.geometry import shape,box,mapping
from shapely.ops import unary_union
from pyproj import Geod
P=Path(__file__).parent;ways=json.load(open(P/'source-ways.geojson'))['features'];GEOD=Geod(ellps='WGS84')
specs=[dict(name='Fácánoskert-lakópark',roads=['Fácánoskert'],scope=[18.320,47.624,18.332,47.633],sourceUrl='https://tata.hu/mindennapok/egeszsegugy/egeszsegugyi-alapellatas/fogorvosok/04-szamu-korzet/',supportingUrls=['https://www.openstreetmap.org/node/1154387633','https://tata.hu/wp-content/uploads/2021/11/kdits_tata_its_08141.pdf'],note='Municipal street documentation explicitly equates Császár Attila utca with Fácános kert. Eight archived OSM ways carrying the older Fácánoskert estate-road name outline the connected housing development. The outer street-vertex envelope estimates its quarter extent; plot depths and newer development phases are unresolved.'),dict(name='Levendulakert',roads=['Levendulakert utca','Vécsey Károly utca'],scope=[18.296,47.637,18.305,47.643],sourceUrl='https://tata.hu/mindennapok/egeszsegugy/egeszsegugyi-alapellatas/felnott-haziorvosok/2-szamu-korzet/',supportingUrls=['https://www.openstreetmap.org/node/2690548887','https://utcak-magyarorszag.openalfa.com/utcak/vecsey-karoly-utca-levendulakert-tata'],note='Municipal documentation confirms Levendulakert utca; the street guide places Vécsey Károly utca in Levendulakert. The named local housing-street network provides a recognizable full built-up estate envelope, not the broader Nagykert/Felső-Tata parent. Outer plot boundaries remain uncertain.'),dict(name='Boglárka apartmanpark',roads=['Boglárka utca','Nyírfa utca','Boróka utca'],scope=[18.337,47.630,18.349,47.638],sourceUrl='https://tata.hu/wp-content/uploads/2021/11/kdits_tata_its_08141.pdf',supportingUrls=['https://www.openstreetmap.org/node/2774661333','https://utcak-magyarorszag.openalfa.com/utcak/nyirfa-utca-boglarka-apartmanpark-tata'],note='The municipal ITS explicitly labels Boglárka apartmanpark on the eastern lakeside. The estate-named street and locally bounded portions of Nyírfa/Boróka streets support this residential envelope. Streets with the same names outside this locality are excluded. Development-phase and parcel extents remain approximate.'),dict(name='Remeteség',roads=['Mária utca','Ágnes utca','Hedvig utca','Ida utca','Irén utca','Erzsébet utca','Ilona utca','Magdolna utca','Margit utca','Klára utca','Judit utca'],scope=[18.331,47.618,18.342,47.628],sourceUrl='https://tata.hu/wp-content/uploads/2021/11/kdits_tata_its_08141.pdf',supportingUrls=['https://www.openstreetmap.org/node/1299482165','https://tata.hu/mindennapok/egeszsegugy/egeszsegugyi-alapellatas/fogorvosok/04-szamu-korzet/'],note='The municipality recognizes Remeteség as a separate quarter and lists its residential street network. This envelope estimates the connected housing part around the source label, not a single building. The broader historic Remeteség forest/golf landscape is not reconstructed; this feature is explicitly a partial quarter footprint.',partial=True)]
features=[]
for s in specs:
 scope=box(*s['scope']);fs=[f for f in ways if f['properties']['name'] in s['roads'] and scope.covers(shape(f['geometry']))]
 poly=unary_union([shape(f['geometry']) for f in fs]).convex_hull
 if poly.geom_type!='Polygon' or not poly.is_valid:raise ValueError(s['name'])
 features.append(dict(type='Feature',id='estimated:west-planning:Tata:'+s['name'],properties=dict(name=s['name'],municipality='Tata',estimated=True,lowConfidence=True,confidence='low',method='Estimated outer envelope of the explicit locally scoped OSM estate street set; convex hull of original source vertices. No point buffer, Voronoi cell or parent-quarter geometry.',sourceUrl=s['sourceUrl'],supportingUrls=s['supportingUrls'],approximationNote=s['note']+' Straight connections between outer street vertices are estimated search-area boundaries, not legal or cadastral lines.',partialFootprint=s.get('partial',False),sourceLineIds=[f['id'] for f in fs],sourcePeriod='Municipal quarter/street evidence; OSM snapshot2026-11-12',boundaryKind='neighbourhood',usableForAddressAssignment=False,areaM2=round(abs(GEOD.geometry_area_perimeter(poly)[0])),license='ODbL-1.0',attribution='© OpenStreetMap contributors'),geometry=mapping(poly)))
(P/'estate-recipes.json').write_text(json.dumps(specs,ensure_ascii=False,indent=2)+'\n');(P/'additional-features.geojson').write_text(json.dumps(dict(type='FeatureCollection',features=features),ensure_ascii=False,indent=2)+'\n');print([(f['properties']['name'],f['properties']['areaM2']) for f in features])
